create table public.profiles (id text primary key check (length(id)=15), auth_id uuid unique not null, email text unique not null, display_name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organizations (id text primary key, name text not null, owner_id text not null references profiles(id), created_at timestamptz not null default now());
create table public.memberships (id text primary key, organization_id text not null references organizations(id), user_id text not null references profiles(id), role text not null check(role in ('owner','admin','member')), created_at timestamptz not null default now(), unique(organization_id,user_id));
create table public.projects (id text primary key, organization_id text not null references organizations(id), name text not null, status text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks (id text primary key, project_id text not null references projects(id), creator_id text not null references profiles(id), assignee_id text references profiles(id), title text not null, description text not null, status text not null check(status in ('todo','in_progress','done','cancelled')), priority text not null check(priority in ('low','medium','high','urgent')), due_date timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.comments (id text primary key, task_id text not null references tasks(id), author_id text not null references profiles(id), body text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.activities (id text primary key, organization_id text not null references organizations(id), project_id text references projects(id), actor_id text not null references profiles(id), action text not null, subject_type text not null, subject_id text not null, created_at timestamptz not null default now());
create index on projects(organization_id); create index on tasks(project_id); create index on comments(task_id); create index on memberships(organization_id,user_id);
create or replace function public.enforce_tenant_keys() returns trigger language plpgsql set search_path='' as $$ begin
 if tg_table_name='organizations' and (tg_op='UPDATE' and new.owner_id<>old.owner_id) then raise exception 'immutable owner'; end if;
 if tg_table_name='projects' and (tg_op='UPDATE' and new.organization_id<>old.organization_id) then raise exception 'immutable tenant'; end if;
 if tg_table_name='tasks' and (tg_op='UPDATE' and (new.project_id<>old.project_id or new.creator_id<>old.creator_id)) then raise exception 'immutable task keys'; end if;
 if tg_table_name='comments' and (tg_op='UPDATE' and (new.task_id<>old.task_id or new.author_id<>old.author_id)) then raise exception 'immutable comment keys'; end if;
 if tg_table_name='memberships' and (tg_op='UPDATE' and (new.organization_id<>old.organization_id or new.user_id<>old.user_id)) then raise exception 'immutable membership keys'; end if;
 return new; end $$;
create trigger organizations_keys before update on organizations for each row execute function public.enforce_tenant_keys();
create trigger projects_keys before update on projects for each row execute function public.enforce_tenant_keys();
create trigger tasks_keys before update on tasks for each row execute function public.enforce_tenant_keys();
create trigger comments_keys before update on comments for each row execute function public.enforce_tenant_keys();
create trigger memberships_keys before update on memberships for each row execute function public.enforce_tenant_keys();
revoke all on all tables in schema public from anon; grant select,insert,update,delete on all tables in schema public to authenticated;
alter table profiles enable row level security; alter table organizations enable row level security; alter table memberships enable row level security; alter table projects enable row level security; alter table tasks enable row level security; alter table comments enable row level security; alter table activities enable row level security;
create or replace function public.current_profile_id() returns text language sql stable security definer set search_path='' as $$ select id from public.profiles where auth_id=auth.uid() $$;
revoke all on function public.current_profile_id() from public; grant execute on function public.current_profile_id to authenticated;
create policy profile_self on profiles for all to authenticated using(auth_id=auth.uid()) with check(auth_id=auth.uid());
create or replace function public.is_org_member(org text) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships m where m.organization_id=org and m.user_id=public.current_profile_id()) $$;
revoke all on function public.is_org_member(text) from public; grant execute on function public.is_org_member(text) to authenticated;
create policy member_org on organizations for all to authenticated using(public.is_org_member(id));
create or replace function public.is_org_admin(org text) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships m where m.organization_id=org and m.user_id=public.current_profile_id() and m.role in ('owner','admin')) $$;
revoke all on function public.is_org_admin(text) from public; grant execute on function public.is_org_admin(text) to authenticated;
create policy member_membership on memberships for select to authenticated using(user_id=public.current_profile_id() or public.is_org_admin(organization_id));
create policy manage_membership on memberships for update to authenticated using(public.is_org_admin(organization_id)) with check(public.is_org_admin(organization_id));
create policy member_project on projects for all to authenticated using(public.is_org_member(organization_id));
create policy member_task on tasks for all to authenticated using(exists(select 1 from projects p where p.id=tasks.project_id and public.is_org_member(p.organization_id)));
create policy member_comment on comments for all to authenticated using(exists(select 1 from tasks t join projects p on p.id=t.project_id where t.id=comments.task_id and public.is_org_member(p.organization_id)));
create policy member_activity on activities for select to authenticated using(public.is_org_member(organization_id));
